from typing import List

class Solution:
    def findBestValue(self, arr: List[int], target: int) -> int:
        lo, hi = 0, max(arr)

        def capped_sum(value: int) -> int:
            return sum(min(x, value) for x in arr)

        while lo < hi:
            mid = (lo + hi) // 2
            if capped_sum(mid) < target:
                lo = mid + 1
            else:
                hi = mid

        x = lo
        sx = capped_sum(x)
        y = max(0, x - 1)
        sy = capped_sum(y)

        if abs(sx - target) < abs(sy - target):
            return x
        return y

