import java.io.*;
import java.util.*;

class Solution {
    public int findBestValue(int[] arr, int target) {
        int lo = 0;
        int hi = 0;
        for (int x : arr) hi = Math.max(hi, x);

        while (lo < hi) {
            int mid = lo + (hi - lo) / 2;
            long sum = 0;
            for (int x : arr) sum += Math.min(x, mid);

            if (sum < target) lo = mid + 1;
            else hi = mid;
        }

        int x = lo;
        long sx = 0;
        long sy = 0;
        int y = Math.max(0, x - 1);

        for (int value : arr) {
            sx += Math.min(value, x);
            sy += Math.min(value, y);
        }

        return Math.abs(sx - (long) target) < Math.abs(sy - (long) target) ? x : y;
    }
}

