#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

int findBestValue(int* arr, int arrSize, int target) {
    int hi = 0;
    for (int i = 0; i < arrSize; ++i) {
        if (arr[i] > hi) hi = arr[i];
    }

    int lo = 0;
    while (lo < hi) {
        int mid = lo + (hi - lo) / 2;
        long long sum = 0;
        for (int i = 0; i < arrSize; ++i) {
            sum += (arr[i] < mid) ? arr[i] : mid;
        }

        if (sum < target) lo = mid + 1;
        else hi = mid;
    }

    int x = lo;
    int y = (x > 0) ? x - 1 : 0;
    long long sx = 0, sy = 0;

    for (int i = 0; i < arrSize; ++i) {
        sx += (arr[i] < x) ? arr[i] : x;
        sy += (arr[i] < y) ? arr[i] : y;
    }

    long long dx = llabs(sx - (long long)target);
    long long dy = llabs(sy - (long long)target);
    return (dx < dy) ? x : y;
}

