public class Main {
    private static int[] parseArray(String line) {
        int start = line.indexOf("[[") + 2;
        int end = line.indexOf("]", start);
        String body = line.substring(start, end);
        if (body.isEmpty()) return new int[0];

        String[] parts = body.split(",");
        int[] arr = new int[parts.length];
        for (int i = 0; i < parts.length; i++) {
            arr[i] = Integer.parseInt(parts[i].trim());
        }
        return arr;
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine().trim();

        int[] arr = parseArray(line);
        int firstClose = line.indexOf(']');
        int comma = line.indexOf(',', firstClose);
        int lastBracket = line.lastIndexOf(']');
        int target = Integer.parseInt(line.substring(comma + 1, lastBracket).trim());

        System.out.println(new Solution().findBestValue(arr, target));
    }
}

